package dk.sdu.cbse.core;
import dk.sdu.cbse.api.*;import java.nio.file.*;
public final class PluginSmokeTest{public static void main(String[]a)throws Exception{GameData d=new GameData();PluginManager p=new PluginManager(d);Path dir=Path.of("plugins");p.reload(dir);if(d.entities().stream().noneMatch(e->e.getType().equals("PLAYER")))throw new AssertionError("Player not loaded");Path jar=dir.resolve("dk.sdu.cbse.player.jar"),off=Path.of("dk.sdu.cbse.player.jar.off");Files.move(jar,off,StandardCopyOption.REPLACE_EXISTING);try{p.reload(dir);if(d.entities().stream().anyMatch(e->e.getType().equals("PLAYER")))throw new AssertionError("Player not removed");}finally{Files.move(off,jar,StandardCopyOption.REPLACE_EXISTING);}p.reload(dir);if(d.entities().stream().noneMatch(e->e.getType().equals("PLAYER")))throw new AssertionError("Player not reloaded");System.out.println("PASS: component removed and installed without recompilation");}}